from itertools import combinations, product
from collections import Counter
from fractions import Fraction as Q

# Reference anchors (-3,0),(3,0); H generated by x and y reflections.
def transform(p,g):return ((-1)**(g&1)*p[0],(-1)**((g>>1)&1)*p[1])
def char(c,g):return (-1)**((c&g).bit_count())
def dist(p,q):return sum((a-b)**2 for a,b in zip(p,q))
def orbit(s):return min(tuple(sorted(transform(p,g) for p in s)) for g in range(4))
def law(s,r):
    # symmetrized anchored coordinate distribution: unnormalized total mass 4*len(s)^r
    return Counter(tuple(transform(p,g) for p in t) for g in range(4) for t in product(s,repeat=r))
def anchored(s,r):
    a,b=(-3,0),(3,0)
    return Counter(tuple(dist(t[i],t[j]) for i,j in combinations(range(r+2),2))
        for x,y in ((a,b),(b,a)) for v in product(s,repeat=r) for t in [(x,y)+v])
def project(s,c):
    h=Counter()
    for g in range(4):
        for p in s:h[transform(p,g)]+=char(c,g)
    return {k:v for k,v in h.items() if v}
def tensor_entry(h,cs,ps):
    return sum(v*prod_char(ps,t,cs) for t,v in h.items())
def prod_char(ps,t,cs):
    v=1
    for p,x,c in zip(ps,t,cs):v*=sum(char(c,g) for g in range(4) if transform(x,g)==p)
    return v

def main():
    # 4 free interior points on a single generic H orbit, plus one asymmetric fixed-axis orbit.
    grid=[(1,1),(-1,1),(1,-1),(-1,-1),(2,0),(-2,0),(0,1),(0,-1)]
    anchors=((-3,0),(3,0)); cases=0; buckets={}; collisions=0
    for k in range(len(grid)+1):
        for a in combinations(grid,k):
            s=anchors+a
            assert sum(dist(p,q)==36 for p,q in combinations(s,2))==1
            assert max(dist(p,q) for p,q in combinations(s,2))==36
            if tuple(sorted(s))!=orbit(s):continue
            l=law(s,3); sig=tuple(sorted(l.items())); can=orbit(s)
            assert sig not in buckets or buckets[sig]==can
            buckets[sig]=can;cases+=1
            # distances with anchors give exactly the same equality classes as symmetrized coordinates
            # check pairwise via dictionaries of signatures
    print('unique-diameter dihedral classes:',cases,'distinct anchored third moment laws:',len(buckets))
    dkeys={};lkeys={};tests=0
    for k in range(len(grid)+1):
        for a in combinations(grid,k):
            s=anchors+a
            if tuple(sorted(s))!=orbit(s):continue
            for r in (1,2,3):
                d=(r,tuple(sorted(anchored(s,r).items())))
                l=(r,tuple(sorted(law(s,r).items())))
                assert d not in dkeys or dkeys[d]==l
                assert l not in lkeys or lkeys[l]==d
                dkeys[d]=l;lkeys[l]=d;tests+=1
    print('distance/coordinate signature crosschecks:',tests)
    # weighted rational laws: one four-point orbit with positive integer masses.
    # anchor mass equal, first/second invariant tensors can lose the product of three signs.
    pts=((1,1),(-1,1),(1,-1),(-1,-1))
    def weights(signs):return tuple(4+sum(signs[c-1]*char(c,g) for c in (1,2,3)) for g in range(4))
    wa,wb=weights((1,1,1)),weights((1,1,-1))
    def wlaw(w,r):
        from math import prod
        return Counter({t:sum(prod(w[pts.index(transform(p,g))] for p in t) for g in range(4)) for t in product(pts,repeat=r)})
    assert wlaw(wa,1)==wlaw(wb,1) and wlaw(wa,2)==wlaw(wb,2)
    assert wlaw(wa,3)!=wlaw(wb,3)
    print('weighted orbit witness:',wa,wb,'first two tensors equal; third differs')
    print('all assertions passed')
if __name__=='__main__':main()
